import heapq
import math


def _cosine(a, b):
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(x * x for x in b))
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (norm_a * norm_b)


def top_k_similar(query, vectors, k):
    if k < 1:
        raise ValueError("k must be at least 1")
    scored = ((index, _cosine(query, vector)) for index, vector in enumerate(vectors))
    # nlargest by (score, then the lower index): -index makes the lower index "larger" on equal scores
    return heapq.nlargest(k, scored, key=lambda pair: (pair[1], -pair[0]))
